    18	
    19	    public Customer(String cpf) {
    20	        this.cpf = cpf;
    21	        this.creditBalance = BigDecimal.ZERO.setScale(2);
    22	    }
    23	
    24	    public String getCpf() {
    25	        return cpf;
    26	    }
    27	
    28	    public Money getCreditBalance() {
    29	        return new Money(creditBalance);
    30	    }
    31	
    32	    public void addCredit(Money amount) {
    33	        this.creditBalance = this.creditBalance.add(amount.value());
    34	    }
    35	
    36	    public void removeCredit(Money amount) {
    37	        this.creditBalance = this.creditBalance.subtract(amount.value());
    38	    }
    39	}
